"""Tests for the strip-parallel heat-diffusion simulation.

Covers:
  * exact (bitwise) equality of the 4-thread result vs. the sequential oracle,
  * fixed-boundary invariant and shape preservation,
  * determinism across repeated parallel runs,
  * watchdog: the whole threaded run joins well under 10 s.
"""

from __future__ import annotations

import time

import pytest

from grid import (
    DEFAULT_ITERATIONS,
    GRID_SIZE,
    WATCHDOG_SECONDS,
    ParallelHeatSimulator,
    initial_grid,
)
from reference import sequential_reference


@pytest.fixture(scope="module")
def start_grid() -> list[list[float]]:
    return initial_grid()


@pytest.fixture(scope="module")
def reference_result(start_grid: list[list[float]]) -> list[list[float]]:
    return sequential_reference(start_grid, iterations=DEFAULT_ITERATIONS)


@pytest.fixture(scope="module")
def parallel_result(start_grid: list[list[float]]) -> list[list[float]]:
    return ParallelHeatSimulator(n_threads=4).simulate(
        start_grid, iterations=DEFAULT_ITERATIONS
    )


def test_shapes_preserved(parallel_result: list[list[float]]) -> None:
    assert len(parallel_result) == GRID_SIZE
    assert all(len(row) == GRID_SIZE for row in parallel_result)


def test_boundaries_are_fixed(
    start_grid: list[list[float]],
    parallel_result: list[list[float]],
) -> None:
    n = GRID_SIZE
    for j in range(n):
        assert parallel_result[0][j] == start_grid[0][j]
        assert parallel_result[n - 1][j] == start_grid[n - 1][j]
        assert parallel_result[j][0] == start_grid[j][0]
        assert parallel_result[j][n - 1] == start_grid[j][n - 1]


def test_parallel_matches_sequential_exactly(
    parallel_result: list[list[float]],
    reference_result: list[list[float]],
) -> None:
    """The oracle: bitwise float equality, cell by cell."""
    assert len(parallel_result) == len(reference_result)
    for i, (prow, rrow) in enumerate(zip(parallel_result, reference_result)):
        assert prow == rrow, f"row {i} differs from sequential reference"


def test_parallel_run_is_deterministic(
    start_grid: list[list[float]],
    parallel_result: list[list[float]],
) -> None:
    again = ParallelHeatSimulator(n_threads=4).simulate(
        start_grid, iterations=DEFAULT_ITERATIONS
    )
    assert again == parallel_result


def test_diffusion_actually_happens(
    start_grid: list[list[float]], parallel_result: list[list[float]]
) -> None:
    # The hot interior must cool down; a cold point adjacent to it warms up.
    assert parallel_result[50][50] < start_grid[50][50]
    assert parallel_result[39][50] > start_grid[39][50]


def test_watchdog_whole_test_joins_under_10s(
    start_grid: list[list[float]], parallel_result: list[list[float]]
) -> None:
    """Wall-clock budget: full 50-iteration 4-thread run joins in < 10 s.

    ``parallel_result`` is module-scoped, so measure a fresh run here to
    exercise the watchdog path end-to-end inside this test.
    """
    sim = ParallelHeatSimulator(n_threads=4)
    t0 = time.monotonic()
    out = sim.simulate(start_grid, iterations=DEFAULT_ITERATIONS)
    elapsed = time.monotonic() - t0
    assert out == parallel_result
    assert elapsed < WATCHDOG_SECONDS, f"run took {elapsed:.3f}s (budget 10s)"


def test_watchdog_detects_hang() -> None:
    """A stuck worker is caught by the watchdog instead of hanging forever."""

    import threading

    from grid import _strip_bounds

    class StalledSimulator(ParallelHeatSimulator):
        def simulate(self, grid, iterations=DEFAULT_ITERATIONS, watchdog_seconds=None):
            # Reimplement minimally with an artificially stalled thread 0.
            n = len(grid)
            barrier = threading.Barrier(self.n_threads)
            workers = []

            def worker(t):
                if t == 0:
                    return  # never reaches the barrier -> siblings would hang
                try:
                    lo, hi = _strip_bounds(n, self.n_threads, t)
                    for _ in range(iterations):
                        for i in range(lo, hi):
                            if i == 0 or i == n - 1:
                                continue
                            for j in range(1, n - 1):
                                grid[i][j] = grid[i][j]  # no-op work
                        barrier.wait()
                except threading.BrokenBarrierError:
                    pass

            for t in range(self.n_threads):
                th = threading.Thread(target=worker, args=(t,))
                th.start()
                workers.append(th)
            for th in workers:
                th.join(timeout=self.watchdog_budget)
                if th.is_alive():
                    raise TimeoutError("watchdog fired")

    sim = StalledSimulator(n_threads=4)
    sim.watchdog_budget = 2.0
    t0 = time.monotonic()
    with pytest.raises(TimeoutError):
        sim.simulate(initial_grid(), iterations=1)
    assert time.monotonic() - t0 < WATCHDOG_SECONDS

